using System.Collections.Generic;
using UnityEngine;
namespace SokobanStudio {
public sealed class WarehouseArt : System.IDisposable {
readonly Dictionary<string,Sprite> sprites=new Dictionary<string,Sprite>();
 public static string WallKey(LevelData d,Cell c){int mask=0;var offsets=new[]{new Cell(0,-1),new Cell(1,0),new Cell(0,1),new Cell(-1,0)};for(int i=0;i<4;i++){var n=c+offsets[i];if(n.x>=0&&n.y>=0&&n.x<d.width&&n.y<d.height&&d.terrain[n.y*d.width+n.x]==Terrain.Wall)mask|=1<<i;}return "wall"+mask;}
 public Sprite Art(string kind){if(sprites.TryGetValue(kind,out var existing))return existing;var tex=new Texture2D(64,64);tex.filterMode=FilterMode.Bilinear;for(int y=0;y<64;y++)for(int x=0;x<64;x++){float dx=Mathf.Abs(x-31.5f),dy=Mathf.Abs(y-31.5f);Color c=Color.clear;if(kind=="floor")c=(x<2||y<2)?new Color(.28f,.35f,.43f):new Color(.32f,.39f,.47f);else if(kind.StartsWith("wall")){int mask=kind.Length>4?int.Parse(kind.Substring(4)):0;bool inside=(dx<30||x<32&&(mask&8)!=0||x>=32&&(mask&2)!=0)&&(dy<30||y<32&&(mask&4)!=0||y>=32&&(mask&1)!=0);if(inside){c=new Color(.17f,.23f,.31f);if((y>53&&(mask&1)==0)||(x>57&&(mask&2)==0))c=new Color(.35f,.45f,.56f);if(x%24==0&&y>8&&y<54)c*=.92f;}}else if(kind=="goal"){float r=Mathf.Max(dx,dy);if(r<25)c=r>20?new Color(.3f,.9f,.57f):new Color(.08f,.3f,.23f);if(dx<3&&dy<13||dy<3&&dx<13)c=new Color(.4f,1,.65f);}else if(kind=="robot"||kind=="robotblink"){if(dx<27&&dy<27&&dx+dy<49)c=new Color(.12f,.48f,.86f);if(dx<20&&dy<23)c=new Color(.86f,.93f,1);if(dx<18&&y>27&&y<47)c=new Color(.05f,.16f,.27f);if((x>19&&x<25||x>38&&x<44)&&y>33&&y<(kind=="robotblink"?35:40))c=new Color(.3f,.85f,1);}else if(kind=="crate"||kind=="docked"){if(dx<28&&dy<28&&dx+dy<52){bool edge=dx>23||dy>23;bool stripe=Mathf.Abs(dx-dy)<3;c=kind=="crate"?(edge?new Color(.39f,.21f,.1f):stripe?new Color(.94f,.66f,.29f):new Color(.72f,.4f,.17f)):(edge?new Color(.08f,.3f,.2f):new Color(.22f,.65f,.39f));if(kind=="docked"&&((x>18&&x<29&&Mathf.Abs(y-(43-x))<3)||(x>=29&&x<47&&Mathf.Abs(y-(x-15))<3)))c=Color.white;}}else c=new Color(.5f,.85f,1,.35f);if(kind=="floor"&&((x==8||x==55)&&(y==8||y==55)))c=new Color(.39f,.46f,.53f);if(kind=="crate"&&x>23&&x<40&&y>25&&y<39)c=(x%4==0)?new Color(.2f,.2f,.2f):new Color(.9f,.86f,.7f);tex.SetPixel(x,y,c);}tex.Apply();var sp=Sprite.Create(tex,new Rect(0,0,64,64),new Vector2(.5f,.5f),64);sprites[kind]=sp;return sp;}
public void Dispose(){foreach(var sp in sprites.Values){Object.Destroy(sp.texture);Object.Destroy(sp);}sprites.Clear();}
}
}
